const assert = require('assert');
const { createStore } = require('../src/store');
const { createApi } = require('../src/api');

function setup(stock = 10) {
  let now = 1000;
  const clock = { advance: (ms) => { now += ms; } };
  const store = createStore({ clock: () => now });
  store.addItem('A', stock);
  return { store, clock };
}

test('reserve returns unique string ids', () => {
  const { store } = setup();
  const a = store.reserve('A', 1, 1000);
  const b = store.reserve('A', 1, 1000);
  assert.strictEqual(typeof a, 'string');
  assert.notStrictEqual(a, b);
  assert.notStrictEqual(a, setup().store.reserve('A', 1, 1000));
});

test('reserve validates qty', () => {
  const { store } = setup();
  for (const qty of [0, -1, 1.5, '2', undefined]) {
    assert.throws(() => store.reserve('A', qty, 1000), /INVALID_QTY/);
  }
});

test('reserve rejects more than available', () => {
  const { store } = setup(5);
  store.reserve('A', 3, 1000);
  assert.throws(() => store.reserve('A', 3, 1000), /INSUFFICIENT_STOCK/);
  assert.throws(() => store.reserve('unknown', 1, 1000), /INSUFFICIENT_STOCK/);
  store.reserve('A', 2, 1000); // exactly what is left
  assert.strictEqual(store.getAvailable('A'), 0);
});

test('available excludes active reservations; stock stays physical', () => {
  const { store } = setup(10);
  store.reserve('A', 4, 1000);
  assert.strictEqual(store.getAvailable('A'), 6);
  assert.strictEqual(store.getStock('A'), 10);
  assert.strictEqual(store.getAvailable('unknown'), 0);
});

test('reservation expires exactly at creation + ttl', () => {
  const { store, clock } = setup(10);
  const id = store.reserve('A', 4, 1000);
  clock.advance(999);
  assert.strictEqual(store.getAvailable('A'), 6);
  clock.advance(1);
  assert.strictEqual(store.getAvailable('A'), 10);
  assert.throws(() => store.confirm(id), /RESERVATION_EXPIRED/);
  assert.strictEqual(store.getStock('A'), 10);
});

test('confirm turns a reservation into a sale', () => {
  const { store } = setup(10);
  const id = store.reserve('A', 4, 1000);
  store.confirm(id);
  assert.strictEqual(store.getStock('A'), 6);
  assert.strictEqual(store.getAvailable('A'), 6);
  assert.throws(() => store.confirm(id), /RESERVATION_NOT_FOUND/);
});

test('confirm rejects unknown and released ids', () => {
  const { store } = setup();
  assert.throws(() => store.confirm('nope'), /RESERVATION_NOT_FOUND/);
  const id = store.reserve('A', 1, 1000);
  store.release(id);
  assert.throws(() => store.confirm(id), /RESERVATION_NOT_FOUND/);
});

test('release frees stock and is idempotent', () => {
  const { store } = setup(10);
  const id = store.reserve('A', 4, 1000);
  store.release(id);
  assert.strictEqual(store.getAvailable('A'), 10);
  store.release(id);
  store.release('nope');
  assert.strictEqual(store.getStock('A'), 10);
});

test('removeItem cannot take reserved stock', () => {
  const { store, clock } = setup(10);
  store.reserve('A', 7, 1000);
  assert.throws(() => store.removeItem('A', 4), /INSUFFICIENT_STOCK/);
  store.removeItem('A', 3);
  assert.strictEqual(store.getStock('A'), 7);
  clock.advance(1000);
  store.removeItem('A', 7);
  assert.strictEqual(store.getStock('A'), 0);
});

test('API: GET /stock includes available', () => {
  const { store } = setup(10);
  store.reserve('A', 3, 1000);
  assert.deepStrictEqual(createApi(store)({ method: 'GET', path: '/stock/A' }), { status: 200, body: { sku: 'A', stock: 10, available: 7 } });
});

test('API: reservation lifecycle', () => {
  const { store, clock } = setup(10);
  const api = createApi(store);
  const res = api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 4, ttlMs: 1000 } });
  assert.strictEqual(res.status, 201);
  assert.strictEqual(typeof res.body.id, 'string');
  assert.deepStrictEqual(api({ method: 'POST', path: `/reservations/${res.body.id}/confirm` }), { status: 200, body: { sku: 'A', stock: 6 } });
  assert.deepStrictEqual(api({ method: 'POST', path: `/reservations/${res.body.id}/confirm` }), { status: 404, body: { error: 'RESERVATION_NOT_FOUND' } });

  const { id } = api({ method: 'POST', path: '/reservations', body: { sku: 'A', qty: 1, ttlMs: 50 } }).body;
